-- 国家/地区基础数据从 Finance 迁移到 Skyline：新建 tb_skyline_country，并按原 key_id 写入 Finance tb_finance_country 现有 137 条数据。
-- 保留原主键，Finance 短信基础价格、SMS 报价、SRM 端口中已存的 countryKeyId 无需改动；重复执行时已存在的主键不会覆盖。
-- 回滚：DROP TABLE `tb_skyline_country`;

CREATE TABLE IF NOT EXISTS `tb_skyline_country` (
    `key_id` int NOT NULL AUTO_INCREMENT COMMENT '表主键',
    `code` varchar(10) NOT NULL COMMENT '国家/地区国际区号',
    `mcc` varchar(4) NOT NULL COMMENT '移动国家代码',
    `cn_name` varchar(64) NOT NULL COMMENT '中文名称',
    `en_name` varchar(64) NOT NULL COMMENT '英文名称',
    `status` varchar(32) NOT NULL COMMENT '国家/地区状态：disable=禁用（国家/地区不可用于新业务）；enable=启用（国家/地区可正常使用）',
    `create_by` varchar(19) NOT NULL COMMENT '创建账号UID',
    `modify_by` varchar(19) NULL COMMENT '更新账号UID',
    `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
    `modify_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
    PRIMARY KEY (`key_id`),
    UNIQUE KEY `uk_tb_skyline_country_code_mcc` (`code`, `mcc`),
    KEY `idx_tb_skyline_country_status` (`status`)
) ENGINE = InnoDB DEFAULT CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Skyline 国家/地区基础数据表';


ALTER TABLE `tb_skyline_country` AUTO_INCREMENT = 1137;
